async function parseJson(res) {
  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    throw new Error(body.error || `Request failed (${res.status})`);
  }
  return await res.json();
}
async function startModelDownload(payload) {
  const res = await fetch("/api/models/download", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  const data = await parseJson(res);
  return data.job;
}
function subscribeDownloadProgress(jobId, onEvent) {
  const source = new EventSource(withSessionToken(`/api/models/download/${jobId}/stream`));
  source.onmessage = (msg) => {
    try {
      onEvent(JSON.parse(msg.data));
    } catch {
    }
  };
  source.onerror = () => {
    if (source.readyState === EventSource.CLOSED) {
      void listModelDownloads().then((jobs) => jobs.find((job) => job.id === jobId)).then((job) => {
        if (!job) return;
        onEvent({
          jobId: job.id,
          status: job.status,
          bytesReceived: job.bytesReceived,
          totalBytes: job.totalBytes,
          error: job.error
        });
      }).catch(() => {
      });
    }
  };
  return () => source.close();
}
async function cancelModelDownload(jobId) {
  const res = await fetch(`/api/models/download/${jobId}/cancel`, { method: "POST" });
  const data = await parseJson(res);
  return data.job;
}
async function listModelDownloads() {
  const res = await fetch("/api/models/downloads");
  const data = await parseJson(res);
  return data.jobs;
}
