function isModelInstalled(modelId, kind = "stt") {
  const list = kind === "stt" ? installedManifest?.stt : installedManifest?.tts;
  return list?.some((row) => row.modelId === modelId) ?? false;
}
function ensureDownloadSubscription(job) {
  if (downloadUnsubs.has(job.id)) return;
  if (job.status !== "queued" && job.status !== "running") return;
  const unsub = subscribeDownloadProgress2(job.id, (event) => {
    const current = activeDownloads2.get(job.id);
    if (current) {
      activeDownloads2.set(job.id, {
        ...current,
        status: event.status,
        bytesReceived: event.bytesReceived,
        totalBytes: event.totalBytes,
        error: event.error ?? null
      });
    }
    void refreshVoicePanelUi();
    if (event.status === "completed" || event.status === "failed" || event.status === "cancelled") {
      downloadUnsubs.get(job.id)?.();
      downloadUnsubs.delete(job.id);
      void refreshInstalledManifest();
    }
  });
  downloadUnsubs.set(job.id, unsub);
}
function renderDownloadProgress(job) {
  const wrap = el9("div", "models-download-progress");
  const pct = job.totalBytes && job.totalBytes > 0 ? Math.min(100, Math.round(job.bytesReceived / job.totalBytes * 100)) : null;
  const bar = el9("div", "models-download-progress__bar");
  bar.style.width = pct != null ? `${pct}%` : "30%";
  if (pct == null) bar.classList.add("is-indeterminate");
  wrap.appendChild(bar);
  wrap.appendChild(
    el9(
      "span",
      "models-download-progress__label",
      pct != null ? `${pct}% \xB7 ${formatBytes2(job.bytesReceived)} / ${formatBytes2(job.totalBytes || 0)}` : `${formatBytes2(job.bytesReceived)} \xB7 ${job.status}`
    )
  );
  return wrap;
}
